UPDATE automation_batches SET frozen_bytes=json_extract(?1,'$.frozenBytes'),digest=json_extract(?1,'$.digest') WHERE batch_id=json_extract(?1,'$.batchId') AND EXISTS (SELECT 1 FROM machine_work_items WHERE work_item_id=json_extract(?1,'$.workItemId')) AND EXISTS (SELECT 1 FROM json_each(CASE WHEN json_valid(frozen_bytes) THEN frozen_bytes ELSE '{}' END,'$.entries') e WHERE json_extract(e.value,'$.kind')='sessionCreate' AND json_extract(e.value,'$.value.workItemId')=json_extract(?1,'$.workItemId'));
